# Generates a fresh release keystore and a matching, git-ignored keystore.properties.
# Use this to replace the key that was previously committed to the repository.
#
# Usage (from the repository root):
#   pwsh -File scripts/generate-release-keystore.ps1
#
# The generated files are never committed: *.keystore and keystore.properties are
# ignored by .gitignore. Back up both the keystore and its password somewhere safe;
# if they are lost you cannot publish updates for this app.

param(
    [string]$KeystorePath = "app/release.keystore",
    [string]$Alias = "docscanner",
    [string]$Dname = "CN=DocScanner, OU=Mobile, O=DocScanner, L=Unknown, ST=Unknown, C=IN"
)

$ErrorActionPreference = "Stop"

if (Test-Path $KeystorePath) {
    throw "$KeystorePath already exists. Remove it first if you really want a new key."
}

Add-Type -AssemblyName System.Security
$bytes = New-Object byte[] 24
[System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($bytes)
$password = [Convert]::ToBase64String($bytes).Replace("/", "_").Replace("+", "-").Replace("=", "")

$keytool = Join-Path $env:JAVA_HOME "bin/keytool.exe"
if (-not (Test-Path $keytool)) {
    $keytool = "keytool"
}

& $keytool -genkeypair `
    -keystore $KeystorePath `
    -alias $Alias `
    -keyalg RSA `
    -keysize 4096 `
    -validity 10000 `
    -storepass $password `
    -keypass $password `
    -dname $Dname

if ($LASTEXITCODE -ne 0) {
    throw "keytool failed with exit code $LASTEXITCODE"
}

$properties = @(
    "# Generated by scripts/generate-release-keystore.ps1. Never commit this file.",
    "storeFile=$KeystorePath",
    "storePassword=$password",
    "keyAlias=$Alias",
    "keyPassword=$password"
) -join "`n"

Set-Content -Path "keystore.properties" -Value $properties -Encoding UTF8

Write-Host ""
Write-Host "Created $KeystorePath and keystore.properties."
Write-Host "Back both files up now. Losing them makes future updates impossible."
Write-Host "Users on the old key must uninstall and reinstall the app."
